+          callSite: obj.callSite,
+          model: obj.model,
+          inputTokens: numericOr(obj.inputTokens),
+          cacheCreationInputTokens: numericOr(obj.cacheCreationInputTokens),
+          cacheReadInputTokens: numericOr(obj.cacheReadInputTokens),
