+    window: { days: windowDays, since: cutoffKey },
+    ceilingUsd,
+    totalDaysObserved: recent.length,
+    breachCount: breaches.length,
+    days: recent.map((d) => ({
+      date: d.date,
+      calls: d.calls,
+      totalUsd: Math.round(d.totalUsd * 10000) / 10000,
+    })),
